<?php namespace App\Http\Controllers; use App\Models\Product; use App\Models\Shipment; class HomeController extends Controller{public function __invoke(){$products=Product::with(['country','variants','preorder'])->where('active',true)->latest()->take(6)->get();$tracking=Shipment::with('country')->where('visible_publicly',true)->latest()->take(6)->get();return view('home',compact('products','tracking'));}}
